solution.css:
/* Lima Bistro · style.css */

/* Step 5: the whole page */
body {
  margin: 0;
  font-family: Arial, sans-serif;
  background-color: #f7f5fb;
  color: #222222;
}

img {
  max-width: 100%;
}

/* Step 6: the header bar */
header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 16px 24px;
  background-color: #602b7a;
  color: #ffffff;
}

.logo {
  margin: 0;
  font-size: 24px;
  font-weight: bold;
}

/* Step 7: the navigation links in a row */
nav ul {
  display: flex;
  gap: 24px;
  list-style: none;
  margin: 0;
  padding: 0;
}

nav a {
  color: #ffffff;
  font-weight: bold;
  text-decoration: none;
}

#nav-btn {
  display: none;
}

/* Step 8: the hero */
.hero {
  padding: 80px 20px;
  background-color: #43235f;
  color: #ffffff;
  text-align: center;
}

.btn {
  display: inline-block;
  padding: 12px 24px;
  border-radius: 8px;
  background-color: #d4de00;
  color: #43235f;
  font-weight: bold;
  text-decoration: none;
}

/* Step 9: the content and the dish cards */
main {
  max-width: 900px;
  margin: 0 auto;
  padding: 0 20px;
}

.dishes {
  display: flex;
  gap: 20px;
}

.dish {
  flex: 1;
  padding: 16px;
  background-color: #ffffff;
  border: 1px solid #e0d6ea;
  border-radius: 12px;
}

.price {
  color: #602b7a;
  font-weight: bold;
}

td {
  padding: 6px 16px 6px 0;
}

footer {
  margin-top: 40px;
  padding: 20px;
  background-color: #43235f;
  color: #ffffff;
  text-align: center;
}

/* Step 10: the phone version (screens up to 600px wide) */
@media (max-width: 600px) {
  header {
    flex-wrap: wrap;
  }

  #nav-btn {
    display: block;
    padding: 8px 14px;
    border: 2px solid #ffffff;
    border-radius: 8px;
    background-color: transparent;
    color: #ffffff;
    font-size: 16px;
    cursor: pointer;
  }

  nav {
    display: none;
    width: 100%;
  }

  nav.open {
    display: block;
  }

  nav ul {
    flex-direction: column;
    gap: 12px;
    padding-top: 16px;
  }

  .dishes {
    flex-direction: column;
  }
}

solution.js:
// Lima Bistro · script.js

// Step 11: open and close the navigation on phones
const navBtn = document.querySelector("#nav-btn");
const nav = document.querySelector("nav");

navBtn.addEventListener("click", () => {
  nav.classList.toggle("open");
});

// Step 12: close the navigation when a link is chosen
const links = document.querySelectorAll("nav a");

links.forEach((link) => {
  link.addEventListener("click", () => {
    nav.classList.remove("open");
  });
});
